from datetime import datetime

# ApiError est fournie par l'environnement :
# class ApiError(Exception):
#     def __init__(self, status, retry_after=None): self.status, self.retry_after = status, retry_after


def _is_retryable(exc):
    if isinstance(exc, TimeoutError):
        return True
    return isinstance(exc, ApiError) and (exc.status == 429 or 500 <= exc.status <= 599)


def _fetch_with_retry(fetch_page, sleep, page, max_attempts):
    for attempt in range(1, max_attempts + 1):
        try:
            return fetch_page(page)
        except Exception as exc:
            if not _is_retryable(exc) or attempt == max_attempts:
                raise                              # non retryable, ou dernière tentative : on relève tel quel
            if isinstance(exc, ApiError) and exc.status == 429 and exc.retry_after is not None:
                delay = exc.retry_after            # 0 est une valeur valide
            else:
                delay = 2 ** (attempt - 1)         # 1, 2, 4, ...
            sleep(delay)


def sync_orders(fetch_page, sleep, max_attempts=4):
    latest = {}                                    # id -> (instant, item)
    page = 1
    while page is not None:
        body = _fetch_with_retry(fetch_page, sleep, page, max_attempts)
        for item in body["items"]:
            ts = datetime.fromisoformat(item["updated_at"])   # comparaison d'instants, pas de chaînes
            known = latest.get(item["id"])
            if known is None or ts >= known[0]:    # >= : à instant égal, le dernier reçu gagne
                latest[item["id"]] = (ts, item)
        page = body["next_page"]
    return [latest[i][1] for i in sorted(latest)]

